=<!doctype html>
<html lang="pt-BR">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Fazer login · Emissão de documentos</title>
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Roboto:wght@400;500&display=swap">
<style>
  * { box-sizing: border-box; }
  body { margin: 0; min-height: 100vh; display: flex; align-items: center; justify-content: center;
         background: #f0f4f9; color: #1f1f1f; font: 400 14px Roboto, arial, sans-serif; }
  main { width: min(1040px, 100%); background: #fff; border-radius: 28px; padding: 36px;
         display: grid; grid-template-columns: 1fr 1fr; gap: 24px; min-height: 384px; }
  img { height: 80px; width: auto; margin: -16px 0 8px -18px; }
  h1 { margin: 0 0 16px; font-size: 36px; line-height: 44px; font-weight: 400; }
  .sub { margin: 0; font-size: 16px; line-height: 24px; }
  .direita { display: flex; flex-direction: column; justify-content: space-between; gap: 32px; padding-top: 64px; }
  .aviso { margin: 0 0 24px; padding: 12px 16px; border-radius: 12px; background: #fce8e6; color: #b3261e; font-size: 14px; }
  .info { margin: 0; color: #444746; font-size: 14px; line-height: 20px; }
  .acoes { display: flex; justify-content: flex-end; }
  a.google { display: inline-flex; align-items: center; gap: 10px; height: 40px; padding: 0 12px;
             border: 1px solid #747775; border-radius: 20px; background: #fff; color: #1f1f1f;
             font: 500 14px Roboto, arial, sans-serif; text-decoration: none; }
  a.google:hover { background: #f8fafd; }
  @media (max-width: 840px) {
    body { background: #fff; align-items: flex-start; }
    main { grid-template-columns: 1fr; border-radius: 0; padding: 24px; min-height: 0; }
    .direita { padding-top: 0; }
    h1 { font-size: 28px; line-height: 36px; }
  }
</style>
</head>
<body>
<main>
  <div>
    {{ $json.logo_url ? '<img src="' + $json.logo_url + '" alt="">' : '' }}
    <h1>Fazer login</h1>
    <p class="sub">Use a conta Google {{ $json.emissor ? 'da ' + $json.emissor : 'da escola' }} para continuar na emissão de documentos</p>
  </div>
  <div class="direita">
    <div>
      {{ $json.aviso ? '<p class="aviso">' + $json.aviso + '</p>' : '' }}
      <p class="info">Acesso restrito à equipe. A senha é digitada só na página do Google; esta página não a recebe.</p>
    </div>
    <div class="acoes"><a class="google" href="{{ $json.google }}"><svg viewBox="0 0 48 48" width="20" height="20" aria-hidden="true"><path fill="#EA4335" d="M24 9.5c3.54 0 6.71 1.22 9.21 3.6l6.85-6.85C35.9 2.38 30.47 0 24 0 14.62 0 6.51 5.38 2.56 13.22l7.98 6.19C12.43 13.72 17.74 9.5 24 9.5z"/><path fill="#4285F4" d="M46.98 24.55c0-1.57-.15-3.09-.38-4.55H24v9.02h12.94c-.58 2.96-2.26 5.48-4.78 7.18l7.73 6c4.51-4.18 7.09-10.36 7.09-17.65z"/><path fill="#FBBC05" d="M10.53 28.59c-.48-1.45-.76-2.99-.76-4.59s.27-3.14.76-4.59l-7.98-6.19C.92 16.46 0 20.12 0 24c0 3.88.92 7.54 2.56 10.78l7.97-6.19z"/><path fill="#34A853" d="M24 48c6.48 0 11.93-2.13 15.89-5.81l-7.73-6c-2.15 1.45-4.92 2.3-8.16 2.3-6.26 0-11.57-4.22-13.47-9.91l-7.98 6.19C6.51 42.62 14.62 48 24 48z"/></svg><span>Fazer login com o Google</span></a></div>
  </div>
</main>
</body>
</html>
